param(
  [string[]]$Aliases = @('x1_01','x1_21','x2','x2_exp','x3','x3_exp'),
  [string]$OutDir = 'T:\1S\wsl_exchange\work_epf_112_9\logs\auto'
)
$ErrorActionPreference = 'Stop'
. '\\wsl.localhost\Ubuntu\{PROJECT_ROOT}\scripts\1c-com-common.win.ps1'
function D([string]$b64){ [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)) }
function T([object]$v){ if($null -eq $v){'<null>'} else { try{([string]$v).Trim()}catch{'<err>'} } }
$queryText = D('')
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$path = Join-Path $OutDir ("{0}_viewtype_predefined_query_matrix.md" -f $stamp)
$lines = New-Object System.Collections.Generic.List[string]
$names = @('zh','nzh','zd','ls','szh','snzh')
$labels = @('ZhilyePomeshcheniya','NezhilyePomeshcheniya','ZdaniyaISooruzheniya','LitsevyeScheta','SostavZhilykhPomeshcheniy','SostavNezhilykhPomeshcheniy')
$lines.Add('# ViewType predefined query matrix')
$lines.Add('')
foreach($alias in $Aliases){
  $lines.Add('## ' + $alias)
  try {
    $ctx = Connect-1CFileBase -Alias $alias
    $q = New-1CQuery -Connection $ctx.Connection -Text $queryText
    $t = $q.Execute().Unload()
    if([int]$t.Count() -gt 0){
      $r = $t.Get(0)
      for($i=0;$i -lt $labels.Count;$i++){
        $base = $i*3
        $lines.Add('- ' + $labels[$i] + ': ref=' + (T $r.Get($base)) + '; code=' + (T $r.Get($base+1)) + '; del=' + (T $r.Get($base+2)))
      }
    }
  } catch {
    $lines.Add('- error: ' + $_.Exception.Message)
  }
  $lines.Add('')
}
Save-Utf8Text -Path $path -Text ([string]::Join("`r`n", $lines))
Write-Output ('REPORT=' + $path)
